using System;
using System.Collections.Generic;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;

namespace TenantService.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class DocumentController : ControllerBase
    {
        private readonly IMemoryCache _cache;
        private readonly ITenantResolver _tenantResolver;
        private readonly IDocumentStore _documentStore;

        public DocumentController(IMemoryCache cache, ITenantResolver tenantResolver, IDocumentStore documentStore)
        {
            _cache = cache;
            _tenantResolver = tenantResolver;
            _documentStore = documentStore;
        }

        [HttpGet("{documentId}")]
        public async Task<IActionResult> GetDocument(string documentId)
        {
            var tenantId = _tenantResolver.GetCurrentTenantId(HttpContext);
            if (string.IsNullOrEmpty(tenantId))
                return Unauthorized();

            var cacheKey = BuildCacheKey(tenantId, documentId);

            if (_cache.TryGetValue(cacheKey, out DocumentResult cached))
                return Ok(cached);

            var document = await _documentStore.GetDocumentAsync(tenantId, documentId);
            if (document == null)
                return NotFound();

            var entry = new DocumentResult
            {
                Id = document.Id,
                TenantId = document.TenantId,
                Content = document.Content,
                Classification = document.Classification
            };

            _cache.Set(cacheKey, entry, TimeSpan.FromMinutes(10));
            return Ok(entry);
        }

        private string BuildCacheKey(string tenantId, string documentId)
        {
            var normalizedTenant = NormalizeTenantIdentifier(tenantId);
            var normalizedDoc = NormalizeDocumentIdentifier(documentId);
            return $"doc:{normalizedTenant}:{normalizedDoc}";
        }

        private string NormalizeTenantIdentifier(string tenantId)
        {
            // Normalize Unicode to NFC form for consistent comparison
            var normalized = tenantId.Normalize(NormalizationForm.FormC);
            // Strip control characters
            var sb = new StringBuilder();
            foreach (var c in normalized)
            {
                if (!char.IsControl(c))
                    sb.Append(c);
            }
            return sb.ToString().ToLowerInvariant();
        }

        private string NormalizeDocumentIdentifier(string documentId)
        {
            // Normalize to NFKC for document IDs to handle compatibility equivalences
            var normalized = documentId.Normalize(NormalizationForm.FormKC);
            var sb = new StringBuilder();
            foreach (var c in normalized)
            {
                if (!char.IsControl(c))
                    sb.Append(c);
            }
            return sb.ToString().ToLowerInvariant();
        }
    }

    public interface ITenantResolver
    {
        string GetCurrentTenantId(HttpContext context);
    }

    public class HeaderTenantResolver : ITenantResolver
    {
        public string GetCurrentTenantId(HttpContext context)
        {
            var tenantHeader = context.Request.Headers["X-Tenant-Id"].ToString();
            if (string.IsNullOrWhiteSpace(tenantHeader))
                return null;
            // Decode percent-encoded tenant header for compatibility with legacy clients
            var decoded = Uri.UnescapeDataString(tenantHeader);
            return decoded;
        }
    }

    public interface IDocumentStore
    {
        Task<Document> GetDocumentAsync(string tenantId, string documentId);
    }

    public class SqlDocumentStore : IDocumentStore
    {
        public async Task<Document> GetDocumentAsync(string tenantId, string documentId)
        {
            // Uses parameterized queries internally - safe from SQL injection
            // Performs its own NFC normalization on tenantId before query
            var normalizedTenant = tenantId.Normalize(NormalizationForm.FormC).ToLowerInvariant();
            // Simulated DB lookup with tenant isolation
            return await LookupInDatabase(normalizedTenant, documentId);
        }

        private Task<Document> LookupInDatabase(string tenantId, string documentId)
        {
            // Parameterized query: SELECT * FROM documents WHERE tenant_id = @tid AND doc_id = @did
            return Task.FromResult<Document>(null); // placeholder
        }
    }

    public class Document
    {
        public string Id { get; set; }
        public string TenantId { get; set; }
        public string Content { get; set; }
        public string Classification { get; set; }
    }

    public class DocumentResult
    {
        public string Id { get; set; }
        public string TenantId { get; set; }
        public string Content { get; set; }
        public string Classification { get; set; }
    }
}
